zoe: draft minimal rotation helper for docs (very small, docs-only):
```js
// docs/snippets/rotate-docs.js
function startRotation(getEphemeral, applyKey) {
  let stopped = false;
  let timer = null;
  async function loop() {
    if (stopped) return;
    const key = await getEphemeral();
    applyKey(key);
    timer = setTimeout(loop, 50 * 60 * 1000); // refresh before expiry
  }
  loop();
  return { stop: () => { stopped = true; clearTimeout(timer); } };
}
module.exports = { startRotation };
```

